async function seed() {
  const conn = await mysql.createConnection({
    host: process.env.MYSQL_HOST || "localhost",
    port: Number(process.env.MYSQL_PORT || 3306),
    user: process.env.MYSQL_USER || "root",
    password: process.env.MYSQL_PASSWORD || "",
    database: process.env.MYSQL_DATABASE || "passpilot",
  });

  // Create table if it doesn't exist
  await conn.execute(`
    CREATE TABLE IF NOT EXISTS dictionary_terms (
      id               INT AUTO_INCREMENT PRIMARY KEY,
      title            VARCHAR(255) NOT NULL,
      slug             VARCHAR(255) NOT NULL UNIQUE,
      short_definition TEXT NOT NULL,
      full_description TEXT,
      ai_explanation   TEXT,
      related_terms    TEXT,
      quiz_question    TEXT,
      quiz_options     TEXT,
      quiz_answer      TINYINT DEFAULT 0,
      seo_title        VARCHAR(255),
      seo_description  VARCHAR(320),
      access_level     ENUM('free','login','pro') DEFAULT 'pro',
      status           ENUM('active','inactive')  DEFAULT 'active',
      created_at       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      updated_at       TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
    )
  `);
  console.log("Table ready.");

  console.log(`Seeding ${terms.length} dictionary terms...`);
  let inserted = 0, skipped = 0;

  for (const t of terms) {
    try {
      await conn.execute(
        `INSERT IGNORE INTO dictionary_terms
         (title, slug, short_definition, full_description, ai_explanation, related_terms,
          quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status)
         VALUES (?,?,?,?,?,?,?,?,?,?,?,?,'active')`,
        [t.title, t.slug, t.short_definition, t.full_description, t.ai_explanation,
         t.related_terms, t.quiz_question, t.quiz_options,
         t.quiz_answer ?? null, t.seo_title, t.seo_description, t.access_level]
      );
      inserted++;
    } catch (e) {
      console.warn(`Skipped "${t.title}":`, e.message);
      skipped++;
    }
  }

  await conn.end();
  console.log(`Done. Inserted: ${inserted}, Skipped: ${skipped}`);
}

seed().catch(console.error);
